var UTILITIES={getRandomInt:function(e,t){return Math.floor(Math.random()*(t-e+1)+e)},getNumberWithEnding:function(e){return e<=0?0:e%100==10||e%100==11||e%100==12||e%100==13||e%10==4||e%10==5||e%10==6||e%10==7||e%10==8||e%10==9||e%10==0?e.toString()+"th":e%10==1?e.toString()+"st":e%10==2?e.toString()+"nd":e%10==3?e.toString()+"rd":void 0},getTimeDisplay:function(e){if(console.log("timeSeconds: %s",e),e>0){var t=Math.floor(e/60),n=e-60*t;return UTILITIES.strPadLeft(t,"0",2)+":"+UTILITIES.strPadLeft(n,"0",2)}return"00:00"},strPadLeft:function(e,t,n){return(new Array(n+1).join(t)+e).slice(-n)},titleCase:function(e){let t="";if(e){t=e.toLowerCase().split(" ");for(var n=0;n<t.length;n++)t[n]=t[n].charAt(0).toUpperCase()+t[n].substring(1);t=t.join(" ")}return t},splitCamelCase:function(e){return e?e.replace(/([A-Z]+)/g,"$1").replace(/([A-Z][a-z])/g," $1"):""},splitAndTitleCase:function(e){return UTILITIES.titleCase(UTILITIES.splitCamelCase(e))},getFullTeamName:function(e,t){return e?self.awayTeamID()===t?e+" (away)":e+" (home)":""},getTeamImagePath:function(e){return e?self.awayTeamID()===e?self.awayTeamInfo().teamImage():self.homeTeamInfo().teamImage():""}},HELPERS={getDownText:function(e,t){if("function"==typeof self.isTwoPointConversion&&self.isTwoPointConversion())return"1st & GOAL";let n="";return t&&(n=t.toString()),self.yardsToTouchdown()<=self.yardsToFirst()&&(n="GOAL"),UTILITIES.getNumberWithEnding(e)+" & "+n},getYardText:function(){return(self.currentTeamWithBall()===self.homeTeamID()===self.yardsToTouchdown()>50?self.homeTeamInfo().teamName():self.awayTeamInfo().teamName())+" "+self.currentBallSpot()}};